import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { errorTrackingRecommendationsSourceMapsExamplesRetrieve } from '../../../generated/api'
import type { MissingSymbolsExamplesApi, SymbolsPlatformEnumApi } from '../../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceMapsExamplesLogicValues {
    currentTeamIdStrict: number | string // teamLogic
    examples: MissingSymbolsExamplesApi | null
    examplesFailed: boolean
    examplesLoading: boolean
    isOpen: boolean
    platform: SymbolsPlatformEnumApi | null
    selectedExampleIndex: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sourceMapsExamplesLogicActions {
    closeExamples: () => {
        value: true
    }
    loadExamples: (platform: SymbolsPlatformEnumApi) => SymbolsPlatformEnumApi
    loadExamplesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadExamplesSuccess: (
        examples: MissingSymbolsExamplesApi,
        payload?: SymbolsPlatformEnumApi
    ) => {
        examples: MissingSymbolsExamplesApi
        payload?: SymbolsPlatformEnumApi
    }
    openExamples: (platform: SymbolsPlatformEnumApi) => {
        platform: SymbolsPlatformEnumApi
    }
    selectExample: (index: number) => {
        index: number
    }
}

export type sourceMapsExamplesLogicType = MakeLogicType<sourceMapsExamplesLogicValues, sourceMapsExamplesLogicActions>

export const sourceMapsExamplesLogic = kea<sourceMapsExamplesLogicType>([
    path(['products', 'error_tracking', 'scenes', 'ErrorTrackingScene', 'banners', 'sourceMapsExamplesLogic']),

    connect(() => ({
        values: [teamLogic, ['currentTeamIdStrict']],
    })),

    actions({
        openExamples: (platform: SymbolsPlatformEnumApi) => ({ platform }),
        closeExamples: true,
        selectExample: (index: number) => ({ index }),
    }),

    loaders(({ values }) => ({
        examples: [
            null as MissingSymbolsExamplesApi | null,
            {
                loadExamples: async (platform: SymbolsPlatformEnumApi, breakpoint) => {
                    // A newer request makes the breakpoint drop this result or error, so no stale rows show.
                    try {
                        return await errorTrackingRecommendationsSourceMapsExamplesRetrieve(
                            String(values.currentTeamIdStrict),
                            { platform }
                        )
                    } finally {
                        breakpoint()
                    }
                },
            },
        ],
    })),

    reducers({
        isOpen: [
            false,
            {
                openExamples: () => true,
                closeExamples: () => false,
            },
        ],
        platform: [
            null as SymbolsPlatformEnumApi | null,
            {
                openExamples: (_, { platform }) => platform,
            },
        ],
        // Clear the previous result on open, so a modal for another platform never shows stale rows.
        examples: {
            openExamples: () => null,
        },
        selectedExampleIndex: [
            0,
            {
                selectExample: (_, { index }) => index,
                loadExamplesSuccess: () => 0,
            },
        ],
        examplesFailed: [
            false,
            {
                loadExamples: () => false,
                loadExamplesFailure: () => true,
            },
        ],
    }),

    listeners(({ actions, values }) => ({
        openExamples: ({ platform }) => {
            posthog.capture('error_tracking_source_maps_examples_opened', { platform })
            actions.loadExamples(platform)
        },
        selectExample: ({ index }) => {
            posthog.capture('error_tracking_source_maps_example_selected', {
                platform: values.platform,
                position: index + 1,
                reason: values.examples?.results[index]?.reason,
            })
        },
    })),
])
